err_appinst_drm_type: "Sony 的安装器拒绝了此 PKG 的 DRM 类型。如果主机上有该游戏的文件夹或磁盘镜像，请改为在“游戏”中该游戏的页面上使用“添加到主屏幕（修补 DRM）”：它会在注册前将 applicationDrmType 重写为 'standard'。",
err_appinst_content_type: "Sony 的安装器在当前固件上不接受此 PKG 的内容类型（例如某些补丁 pkg / DLC 格式）。如果您拥有基础游戏的 PKG，它应该仍可安装。",
err_appinst_busy: "Sony 的安装器正忙于另一个安装或一个未完成的 BGFT 任务。请稍等片刻，或检查 PS5 的通知中是否有卡住的下载需要清除，然后重试。",
err_already_installed: "此标题已安装。如果您想重新安装，请先将其卸载。",
err_appinst_oom: "Sony 的安装器在安装中途内存不足。请重启 PS5，重新加载载荷后重试。",
err_install_eagain: "Sony 的安装器正忙 — 错误 0x80020023（EAGAIN）。一个具有相同 content_id 的先前安装仍在 PS5 上排队。请在 PS5 上打开 Settings → Notifications 并清除任何待处理的商店相关条目，或者重启 PS5 以清除陈旧的安装状态。然后重试。",
err_install_dup_register: "Sony 的安装器以 0x80B21106 拒绝了此注册 — 最可能是因为针对相同 content_id 的先前安装仍在 PS5 上排队/运行。请在 PS5 上查看 Settings → Notifications → Downloads，确认它是否已在安装。如果您确实想重新注册（例如上次尝试静默失败了），请先重启 PS5。请勿反复点击开始 — 每次重试只会再次确认 Sony 的响应。",
err_install_http_fetch: "PS5 拒绝了我们为安装发起的 HTTP 获取尝试（0x80B22404）。这与 pkg 的格式无关 — Sony 的安装器一个字节都没读取。这是进程上下文问题：Sony 的 PlayGo 仅将 ShellUI 的进程加入安装端 HTTP 获取的白名单，并拒绝我们的请求。2.2.52 版本提供了一条新的 ShellUI-RPC 安装路径，通过 ShellUI 的进程路由，从而使同样的获取成功。如果您仍看到此错误，说明正在运行的是旧载荷 — 请通过 连接 → 发送 payload 推送最新载荷，重新开始安装，诊断面板应显示 register_path=shellui-rpc。",
err_install_116f_npxs: "PS5 安装器拒绝了此系统 pkg（0x80B2116F）。Sony 的安装器无法完成系统补丁（商店更新、Settings）— 这类内容请在 PS5 本机上使用 Settings → Debug Settings → Game → Package Installer。",
err_install_116f_game: "PS5 安装器拒绝了该 pkg（0x80B2116F）。在 FW 9.60 上，此固件版本缺少我们载荷所用的 BGFT 寄存器；请尝试推送最新载荷（连接 → 发送 payload），如果仍然失败，则该 pkg 可能需要通过 PS5 本机的 Debug Settings → Game → Package Installer 安装。",
err_install_1401: "PS5 的 ShellUI 安装路径拒绝了该请求（0x80B21401）。在 FW 9.60 上，当固件版本缺少我们依赖的 BGFT 寄存器时，通常会与另一层失败同时出现。请尝试通过 连接 → 发送 payload 使用最新载荷，或通过 PS5 本机的 Debug Settings 面板安装。",
err_install_2101: "针对相同内容的先前下载仍在 PS5 上排队。请打开 PS5 的通知面板，将其清除后重试安装。",
err_install_80b2_generic: "PS5 的 PlayGo 子系统以 0x80B2_xxxx 错误拒绝了此安装。这是安装获取路径的问题，而非 pkg 解析器 — 您的文件很可能没问题。请发送当前版本的助手（点横幅中的“发送助手”，或在“连接”界面发送）；它的安装路径可绕过最常见的 0x80B2 拒绝类别。",
err_bgft_not_loadable: "您的 PS5 固件未以 ps5upload 可用的方式暴露 Sony 的 BGFT 安装器。请确认 PS5 运行的是当前版本的助手（点横幅中的“发送助手”，或在“连接”界面重新发送），然后重试。如果仍然失败，说明此固件无法用这种方式安装 .pkg：请在 PS5 上直接安装（设置 → 系统 → 调试设置 → 游戏 → Package Installer），如果是游戏文件夹或磁盘镜像，请在“游戏”中该游戏的页面上使用“添加到主屏幕”。",
err_install_enoent_dlc: "这看起来像是一个 DLC pkg（content_id {contentId}）。Sony 的安装器需要先安装基础游戏（{baseTitle}）才能安装 DLC，因为安装会从基础游戏的 app_home 读取元数据。请先安装 {baseTitle}，然后重试此 DLC。0x80020002 是内核在尝试跟随基础游戏引用时报告“无此文件”— 并非您的 DLC pkg 有问题。",
err_install_defrag: "您的 PS5 需要碎片整理后的可用空间。请前往 Settings → Storage → Free up space，然后重试。",
err_install_leftover_download: "PS5 通知中残留有下载。请打开 PS5 的通知面板（PS 按钮 → Notifications → Downloads），清除卡住的条目后重试安装。",
err_install_drm_mismatch: "DRM 不匹配 — 此 PKG 对此主机无效。该 pkg 是为其他账户或地区创建的。",
err_install_entitlement: "PKG 授权检查失败。已登录的 PSN 账户不拥有此标题，或地区不匹配。",
err_install_no_free_space: "PS5 上的可用空间不足。请前往 Settings → Storage → Free up space，然后重试。",
err_install_parental: "标题被 PS5 家长/内容控制阻止。请在重试前于 PS5 Settings → Users and Accounts → Family Management 中调整该用户的限制。",
err_install_esrch: "PS5 安装守护进程无法连接到我们的进程（ESRCH = 无此进程）。通常意味着载荷尚未提权 — kstuff/etaHEN 可能未加载。请通过 连接 → 发送 payload 重新发送载荷后重试。",
err_install_bgft_generic: "Sony 的安装服务以 {code} 拒绝了该请求。常见原因：卡住的先前安装（打开 PS5 通知 → Downloads → 清除）、账户/地区错误，或空间不足。如果均不适用，请截取诊断面板并提交错误报告。",
