"pkg.patch_regressed": "重新安装这个更新反而把它移除了——游戏退回到了本体版本。PS5 的安装器会把重复安装的更新当作要撤销的更新。再安装一次即可回到更新后的版本；请避免重复安装游戏已有的更新。",
