"arcpkg.choose": "选择压缩包…",
"arcpkg.help": "适用于在任意文件夹内包含一个或多个 .pkg 文件的 .zip、.7z 或 .rar。只解压其中的安装包，并直接解压到 PS5（这台电脑上不会解压任何内容），然后逐个安装：先装游戏本体，再装更新，最后装 DLC。支持分卷 RAR（.part1.rar、.part2.rar…）：选择第一卷，并把其余分卷放在同一位置。RAR 需要密码时会提示输入；不支持带密码的 ZIP 和 7z。",
