"install.stream.file.help": "选择 .pkg 或 .fpkg，或把它拖到此窗口的任意位置。安装完成前请保持此应用打开；进度显示在上方的队列和“任务”中。",
"install.stream.file.title": "安装一个安装包文件",
"install.tab.stream.lead": "PS5 直接从这台电脑或从链接安装。不会先在 PS5 上放一份副本，因此不需要占用那里的空间，这也是最可靠的安装方式。",
"install.tab.upload.lead": "先把安装包复制到 PS5，再从该副本安装。当 PS5 无法连接到这台电脑（流式安装因网络错误而失败），或想把安装包留在 PS5 上以便日后不借助这台电脑重新安装时使用。",
"install.upload.file.browser": "要从这里把安装包复制到 PS5，需要桌面应用。在网页界面中请使用“流式安装”，或在下方安装已在 PS5 上的安装包。",
"install.upload.file.help": "选择 .pkg 或 .fpkg。副本需要 PS5 上有容纳整个安装包的可用空间，并会一直留在下方列表中，直到你将其删除。",
"install.upload.file.title": "把安装包复制到 PS5 并安装",
"linkcard.confirm.direct": "PS5 自行从链接下载并安装安装包。开始之后不再需要这台电脑，进度显示在 PS5 上（下载），而不是这里。如果 PS5 无法访问该链接，应用会改为通过这台电脑转发。如果索尼的安装程序失败，覆盖安装已安装的游戏可能会将其删除。只使用你信任且有权安装的安装包链接。",
"linkcard.confirm.download": "这台电脑先把整个安装包保存到磁盘，然后安装到 PS5。两个步骤完成前它必须保持开机，并且需要有容纳安装包的可用空间。如果索尼的安装程序失败，覆盖安装已安装的游戏可能会将其删除。只使用你信任且有权安装的安装包链接。",
"linkcard.confirm.stream": "这台电脑下载安装包并立即转发给 PS5，因此在安装完成前它必须保持开机并在线。不会保存到磁盘。如果索尼的安装程序失败，覆盖安装已安装的游戏可能会将其删除。只使用你信任且有权安装的安装包链接。",
