connection_payload_engine_unreachable: "应用无法连接到这台电脑上它自己的引擎，所以无法判断助手是否已在 PS5 上启动。这不是 PS5 的问题：窗口顶部的提示会说明原因，并可以重启引擎。之后请再次点击“发送助手”。（{error}）",
