first_run_description_v3: "按正确顺序加载大多数环境所需的内容：kstuff（让伪造软件包可以安装和运行）、ShadowMount+（将游戏镜像和文件夹显示在 PS5 主屏幕上）以及 ps5upload 自己的助手。PS5 重启后，“连接”页面会再次提供此向导。",
