game_activity_subtitle_v3: "这台 PS5 上玩了什么、玩了多久。跟踪的游玩时间由主机上的 ps5upload 助手统计；主机游玩时间读取自主机自身的记录。",
hardware_description_v2: "助手连接期间，系统信息、运行时间和存储每 5 秒自动刷新。实时温度和 CPU 频率按需读取——点击“读取传感器”。零售固件并不提供所有读数（例如 CPU 使用率），这些显示为短横线。",
