hw_sensor_no_reading: "主机未返回此传感器的读数",
keep_ps5_awake_mode_hint_v2: "定期重置 PS5 的自动待机计时器，使其无法进入待机模式。“上传和安装期间”保护长时间上传（上传失败的常见原因；默认）。“连接期间始终保持”在应用打开期间让每台运行助手的主机都不进入待机模式。在任何模式下，仍可手动让 PS5 进入待机模式。",
kernellog_categories_explainer: "所有类别一开始都显示。Sony 类别是主机自身的子系统，无论运行什么 payload，在每台越狱的 PS5 上都会持续记录日志；它们不是由 ps5upload 引起的。取消勾选以减少噪音。",
payloads_cached_body: "已将 {kb} KB 下载到本地缓存。",
payloads_cached_title: "已缓存 {id} {tag}",
payloads_description_catalog_v2: "精选的第三方 PS5 自制 payload。检查最新版本，下载一次，然后一键发送到 PS5。版本会缓存在本地，因此也可以放到 USB payload 盘上。",
payloads_description_send_v2: "将任意 PS5 payload 文件——.elf、.bin、.js、.lua 或 .jar（kstuff、自定义自制加载器、浏览器阶段漏洞利用、插件脚本、BD-JB JAR）——发送到你的 PS5。流程与“连接”页面相同，只是指向你选择的文件。端口随文件类型而定（.elf/.bin 9021、.jar 9025、.lua 9026、.js 50000）；仅当你的加载器监听其他端口时才修改。",
payloads_download_failed: "下载失败：{id}",
payloads_open_usb_wizard_v2: "制作 USB payload 盘",
payloads_send_failed: "发送失败：{id}",
payloads_sent_body: "Payload v{version} 已发送到 :9021 上的加载器。请查看 PS5 上的通知。",
payloads_sent_body_pm: "端口 9021 没有响应，因此 payload v{version} 改为通过 Payload Manager（:8084）启动。请查看 PS5 上的通知。",
payloads_sent_title: "已发送 {id} → {host}",
peripheral_drive_attachable: "此型号没有内置光驱；这些仅在连接外置光驱时才起作用。",
power_telemetry_title_v2: "累计计数器",
processes_kill_payload_body: "这会终止 payload “{name}”（kstuff、etaHEN 等）。在你再次发送之前，它提供的功能都会停止，需要它的游戏可能无法启动。",
processes_kill_payload_title: "停止 payload “{name}”？",
"profile.np.browser_v2": "登录需要桌面应用：它会获取 np-fake-signin 并发送到 PS5，而网页界面无法做到。",
ps5notif_empty_hint_v2: "当 ps5upload 在电视上显示消息（例如远程游玩 PIN 或开启金手指）时，会列在这里以便你再次查看。这不是 PS5 自身的通知面板；主机不允许我们读取它。",
reset_confirm_body_browser: "这会清除此浏览器为 PS5Upload 保存的所有设置和状态，并重新加载页面。服务器上引擎自身的数据（主机配对、收藏、已保存的服务器、降级移植库、安装历史、日志）不受影响，PS5 上的任何内容也不受影响。此操作无法撤销。",
reset_confirm_body_v2: "这会永久删除所有本地 PS5Upload 数据：设置、已保存的 PS5 及其配对、收藏、已保存的服务器及其密码、降级移植库、安装历史、任务和事件、活动/队列历史、日志、payload 缓存和崩溃报告。不会触及 PS5 上的任何内容。应用将重新加载为初始状态。此操作无法撤销。",
reset_hint_browser: "清除此浏览器为 PS5Upload 保存的所有设置和状态并重新开始。引擎在服务器上保存的内容（主机配对、收藏、已保存的服务器、降级移植库、安装历史、日志）不受影响，PS5 上的任何内容也不受影响。",
reset_hint_v2: "清除 PS5Upload 的所有本地痕迹并重新开始：设置、已保存的 PS5 及其配对、收藏、已保存的服务器及其密码、降级移植库、安装历史、任务和事件、活动/队列历史、日志、payload 缓存和崩溃报告。PS5 上的任何内容都不受影响。上面的“备份 / 恢复”不包括配对、收藏、服务器密码或降级移植库。",
saves_backup_usb_tooltip_v2: "将此存档打包为 zip，保存到设置中指定的存档路径（PS5 上的 USB 驱动器）。它会先复制到这台电脑、打包后再发送回去，因此请保持应用打开；这里的副本之后会被删除。",
saves_description_browser: "PS5 上的存档，每款游戏一个条目。将存档备份为 .zip 或恢复需要桌面应用；在这里你可以查看它们并打开其文件夹。",
