settings_artwork_cache_explain_v2: "游戏封面保存在引擎运行的地方（这台电脑，或网页版的服务器），因此可以立即加载，而不必每次都从 PS5 读取。它们会自动刷新，当你在某台主机上安装或卸载游戏时，该主机的封面会被移除。",
