auto_bringup_label: "自动启动",
auto_bringup_hint: "当已保存的 PS5 的加载器（elfldr，端口 9021）已运行而助手未运行时，应用会自行执行快速启动：先运行你设置的启动播放列表（如有），再发送助手，然后运行自动加载播放列表。每次主机开机只执行一次；从待机模式唤醒后只重新发送助手。加载器出现后会等待约 90 秒，让主机自己的自动加载器先完成。默认关闭。",
