"rpg_user_body": "在主机上选择你要用来游玩的用户。不需要有人守在屏幕前，但该用户必须保持登录。如果用户设置了登录密码，按下开始时“游玩”会请你输入。",
"rpg_account_title": "为该用户设置账户 ID",
"rpg_account_body": "远程游玩通过账户 ID 配对。已关联 PlayStation Network 的用户本身就有；离线用户需要在上方“用户”中设置一个（任何 ID 都可以；请记下来，之后的存档会与它绑定）。",
"rpg_signin_title": "让账户登录 PlayStation Network（离线）",
"rpg_signin_body": "PS5 只允许已登录的账户使用远程游玩。如果主机自身的远程游玩设置是灰色的，请运行下方的离线登录（不会向索尼发送任何内容），然后重启 PS5。此操作可以撤销。",
"rpg_signin_fix": "前往登录",
"rpg_service_title": "开启远程游玩",
"rpg_service_body": "设置 › 系统 › 远程游玩 › 启用远程游玩。本应用可以替你开启，在固件 10.00 及更高版本上还能为该用户授予权限。若之后按开始提示遥控游玩已关闭，请在 PS5 自己的设置中开启：以主机上的开关为准。",
"rpg_rest_title": "允许从待机模式唤醒 PS5",
"rpg_rest_body": "在 设置 › 系统 › 节能 › 待机模式下可用的功能 中开启“保持连接到互联网”和“启用通过网络开启 PS5”。不开启的话，处于待机模式的主机无法被唤醒，网络也会在几秒后休眠。这些只能在主机上查看。",
"rpg_pair_title": "将本应用与主机配对",
"rpg_pair_body": "连接 › 唤醒并登录 › 设置。只需点一下，即可将本应用注册到 PS5（就像配对 PS Remote Play 应用一样），并把密钥保存在这台电脑上。串流、唤醒和登录都使用这些密钥；重置主机或更换用户后请重新操作。",
"rpg_play_title": "开始游玩",
"rpg_play_body": "打开远程游玩并按“开始”：如果主机处于待机模式，本应用会唤醒它、登录并开始串流。可以用连接到这台电脑的手柄、键盘或触摸来游玩。若要改用索尼的 PS Remote Play 应用或 chiaki-ng，请在下方申请 PIN 并在那里输入。",
"rpg_play_fix": "打开远程游玩",
"rpg_title": "设置远程游玩",
