"rpg_t_black_q": "画面一直是黑的、卡顿，或声音有杂音。",
"rpg_t_black_a": "让 PS5 和这台电脑使用有线连接或 5 GHz Wi-Fi，并在远程游玩的设置中尝试 720p 或 30 fps。这台电脑的防火墙必须允许本应用访问局域网（远程游玩使用 TCP 和 UDP 端口 9295–9304）。在浏览器中请使用新版 Chrome、Edge 或 Safari：画面需要 WebCodecs。",
