"collection.send_many_body_v2": "每台 PS5 会收到它缺少的内容：游戏的软件包，或其文件夹、镜像、压缩包，以及已有游戏的更新版本和 DLC。软件包从这台电脑串流；其余内容上传到“上传并安装”中设置的驱动器的 homebrew 文件夹。",
"first_run_step4_body_v3": "将装有 .ffpkg 游戏镜像的 U 盘插入 PS5，ShadowMount+ 会自动挂载它们——它们会出现在“游戏”中。要发送其他文件或安装 .pkg 软件包，请使用“上传并安装”。",
