"fpkg.aboutFake_v2": "生成的是伪造软件包，所以主机在安装前需要加载伪造软件包支持：kstuff（支持 PS5 伪造软件包的版本）、a53_ppr_install_fast.elf 和 shadowmountplus.elf，按此顺序。“上传并安装”页面在安装按钮旁也有相同说明。",
"fpkg.openUpload_v2": "打开“上传并安装”",
"connection_step3_hint_v3": "打开“上传并安装”，拖入游戏文件夹、.exfat 或 .ffpkg 镜像，或 .pkg 软件包。发送的镜像和文件夹会列在“游戏”中该游戏的页面上，点击“挂载”即可将其显示在 PS5 主屏幕上。",
"connection_go_upload_v2": "打开“上传并安装”",
