"payloads_fpkg_ppr_note_v2": "安装伪造软件包还需要 a53_ppr_install_fast.elf，它不在此列表中：没有发布可下载的文件，需从 GitHub 上的源码编译。“上传并安装”页面按顺序列出了伪造软件包所需的全部内容。",
