"err_install_enoent_generic_v2": "Sony 的安装器在安装期间无法打开它所需的某个文件（内核错误 0x80020002 = ENOENT）。如果这是 DLC pkg，说明基础游戏尚未安装——请先安装基础游戏。否则，暂存的软件包可能在上传和安装之间被删除了；请重试一次安装。如果持续失败，请在“上传并安装”中使用“流式安装”，它会直接从这台电脑发送软件包，而不是先复制到主机。",
